python
import os
import asyncio
from datetime import datetime, timezone
from typing import Optional, List

from fastapi import FastAPI, UploadFile, File, HTTPException, Query
from fastapi.responses import StreamingResponse, JSONResponse, FileResponse, HTMLResponse
from fastapi.staticfiles import StaticFiles
from fastapi.middleware.cors import CORSMiddleware

# Obstore: egységes, nagy áteresztésű object storage API (S3, GCS, Azure, local, memory)
# pip install obstore fastapi uvicorn
import obstore as obs  # sync/async top-level függvény API [6][9][12]

app = FastAPI(title="Underdog Drive - ultra-fast object storage")

# CORS engedély a statikus index.html-hez
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

# Backend store kiválasztás env alapján: memory://, file://path, s3://bucket, gcs://bucket
STORE_URL = os.environ.get("STORE_URL", "memory://")  # prod: s3://my-bucket vagy gcs://my-bucket [12][9]
if STORE_URL.startswith("memory://"):
    store = obs.store.MemoryStore()
elif STORE_URL.startswith("file://"):
    # pl: file:///tmp/drive
    store = obs.store.LocalStore(STORE_URL.replace("file://", ""))
elif STORE_URL.startswith("s3://"):
    # anon/public bucket is támogatott, vagy env cred-ekkel automatikus auth [9][12]
    bucket = STORE_URL.replace("s3://", "")
    store = obs.store.S3Store(bucket)
elif STORE_URL.startswith("gcs://"):
    bucket = STORE_URL.replace("gcs://", "")
    store = obs.store.GCSStore(bucket)
else:
    raise RuntimeError("Unsupported STORE_URL, use memory://, file://, s3://, gcs://")

# Egyszerű meta index (kulcs -> dict). Prod-ban használd külső KV-t/DB-t.
INDEX: dict[str, dict] = {}  # gyors prototípus, immut alternatíva: pyrsistent pmap() [6]

# Statikus frontend kiszolgálás (ugyanebből a mappából)
if os.path.exists("index.html"):
    @app.get("/", response_class=HTMLResponse)
    async def root():
        with open("index.html", "r", encoding="utf-8") as f:
            return HTMLResponse(f.read())
else:
    @app.get("/")
    async def root_json():
        return {"message": "Underdog Drive running. Upload via /upload, list via /list."}

def now_iso():
    return datetime.now(timezone.utc).isoformat()

@app.get("/list")
async def list_objects(prefix: Optional[str] = Query(default=None)):
    # Streamelhető listázás obstore-ból, de itt egyszerűsített anyag [12][9]
    entries = []
    async for entry in obs.list_async(store, prefix or ""):
        entries.append({
            "path": entry.path,
            "size": entry.size,
            "last_modified": entry.last_modified.isoformat() if entry.last_modified else None,
            "etag": entry.e_tag,
            "version": entry.version,
        })
    return {"objects": entries, "count": len(entries)}

@app.post("/upload")
async def upload_file(path: str = Query(..., description="Storage key, pl. users/alice/photo.jpg"),
                      file: UploadFile = File(...)):
    # Streaming feltöltés: közvetlenül a kliensből az object store-ba, async API [6][9][1]
    # Olvasó iterator a kliens által streamelt tartalomhoz
    async def file_iter():
        while True:
            chunk = await file.read(1024 * 1024)  # 1 MiB chunk a jó throughputért [12]
            if not chunk:
                break
            yield chunk

    # put_async képes async iteratorból streamelni [12][9]
    await obs.put_async(store, path, file_iter())

    meta = await obs.head_async(store, path)
    INDEX[path] = {
        "path": path,
        "filename": file.filename,
        "content_type": file.content_type,
        "size": meta.size,
        "etag": meta.e_tag,
        "version": meta.version,
        "last_modified": meta.last_modified.isoformat() if meta.last_modified else now_iso(),
        "uploaded_at": now_iso(),
    }
    return {"status": "ok", "meta": INDEX[path]}

@app.get("/download")
async def download_file(path: str = Query(...), start: Optional[int] = None, end: Optional[int] = None):
    # Range letöltés nagy fájlokhoz, alacsony memória footprint [6][9][12]
    if start is not None or end is not None:
        if start is None or end is None or end <= start:
            raise HTTPException(400, "Invalid range")
        # get_range_async byte-szelethez [9]
        data = await obs.get_range_async(store, path, start=start, end=end)
        async def rng():
            yield data
        return StreamingResponse(rng(), media_type="application/octet-stream",
                                 headers={"Content-Range": f"bytes {start}-{end-1}/*"})
    else:
        # Teljes streaming letöltés [12]
        resp = await obs.get_async(store, path)
        async def streamer():
            # chunkelt olvasás a file-like streamből [12]
            async for chunk in resp.iter_bytes_async(chunk_size=1024 * 1024):
                yield chunk
        media = "application/octet-stream"
        if path.endswith(".png"): media = "image/png"
        elif path.endswith(".jpg") or path.endswith(".jpeg"): media = "image/jpeg"
        elif path.endswith(".pdf"): media = "application/pdf"
        return StreamingResponse(streamer(), media_type=media,
                                 headers={"Content-Length": str(resp.meta.size) if resp.meta.size else ""})

@app.delete("/delete")
async def delete_file(path: str = Query(...)):
    await obs.delete_async(store, path)
    INDEX.pop(path, None)
    return {"status": "deleted", "path": path}

@app.get("/head")
async def head(path: str = Query(...)):
    meta = await obs.head_async(store, path)
    return {
        "path": path,
        "size": meta.size,
        "etag": meta.e_tag,
        "version": meta.version,
        "last_modified": meta.last_modified.isoformat() if meta.last_modified else None
    }

# Egyszerű egészség-ellenőrzés
@app.get("/healthz")
async def healthz():
    try:
        # gyors próba az object store-ral [12]
        await obs.put_async(store, "__healthz", b"ok")
        await obs.delete_async(store, "__healthz")
        return {"ok": True}
    except Exception as e:
        raise HTTPException(500, str(e))



