<!doctype html>
<html lang="hu">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Underdog Drive</title>
  <style>
    :root {
      --blur: 18px;
      --glass-bg: rgba(255,255,255,0.12);
      --glass-brd: rgba(255,255,255,0.35);
      --accent: #6ae3ff;
      --accent2: #9b8cff;
      --text: #f6f7fb;
      --muted: #cfd2e2;
      --ok: #42d392;
      --err: #ff6b6b;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center;
      background: radial-gradient(1200px 800px at 20% 10%, #141824, #0a0d14 60%);
      color: var(--text); font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Noto Sans, Ubuntu, Cantarell, Helvetica Neue, Arial, "Apple Color Emoji", "Segoe UI Emoji";
    }
    .wrap {
      width: min(980px, 92vw);
      padding: 28px;
      border-radius: 18px;
      background: linear-gradient(135deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
      backdrop-filter: blur(var(--blur));
      -webkit-backdrop-filter: blur(var(--blur));
      border: 1px solid var(--glass-brd);
      box-shadow: 0 20px 60px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,0.12);
    }
    h1 {
      margin: 0 0 8px; font-weight: 700; letter-spacing: .2px;
      background: linear-gradient(90deg, var(--accent), var(--accent2));
      -webkit-background-clip: text; background-clip: text; color: transparent;
    }
    p { margin: 0 0 18px; color: var(--muted); }
    .row { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; margin-bottom: 16px; }
    .btn {
      padding: 10px 14px; border-radius: 12px; border: 1px solid var(--glass-brd);
      background: linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.06));
      color: var(--text); cursor: pointer; transition: .2s ease; font-weight: 600;
    }
    .btn:hover { transform: translateY(-1px); box-shadow: 0 6px 18px rgba(0,0,0,.25); }
    .btn.acc { background: linear-gradient(180deg, rgba(106,227,255,0.35), rgba(106,227,255,0.15)); border-color: rgba(106,227,255,0.45); }
    .btn.dng { background: linear-gradient(180deg, rgba(255,107,107,0.35), rgba(255,107,107,0.15)); border-color: rgba(255,107,107,0.45); }
    .drop {
      margin-top: 8px; border: 2px dashed rgba(255,255,255,0.25); border-radius: 16px;
