  </style>
</head>
<body>
  <div class="wrap">
    <h1>Underdog Drive</h1>
    <p>Villámgyors, streaming alapú tárhely. Húzd ide a fájlt vagy válaszd ki. <span class="pill">/upload, /list, /download, /delete</span></p>

    <div class="row">
      <input type="text" id="prefix" placeholder="Mappa/prefix (pl. users/alice)" style="flex:1;padding:10px;border-radius:12px;border:1px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.08);color:var(--text)">
      <button class="btn acc" id="refresh">Frissít</button>
      <input type="file" id="file" multiple style="display:none">
      <button class="btn" id="pick">Fájl kiválasztása</button>
    </div>

    <div class="drop" id="drop">Húzd ide a fájlokat feltöltéshez</div>
    <div class="progress" style="margin-top:12px;"><div class="bar" id="bar"></div></div>

    <div class="list" id="list"></div>
  </div>

<script>
const api = location.origin;
const el = (id)=>document.getElementById(id);
const listEl = el('list'), bar = el('bar');

function fmtSize(n){
  if(n==null) return '-';
  const u=['B','KB','MB','GB','TB'];
  let i=0; while(n>=1024 && i<u.length-1){ n/=1024; i++; }
  return n.toFixed(1)+' '+u[i];
}

async function refresh(){
  const prefix = el('prefix').value || '';
  const url = new URL('/list', api);
  if(prefix) url.searchParams.set('prefix', prefix.endsWith('/')?prefix:prefix+'/');
  const r = await fetch(url);
  const j = await r.json();
  render(j.objects || []);
}

function render(items){
  listEl.innerHTML = '';
  if(items.length===0){
    listEl.innerHTML = '<div class="item"><div class="muted">Nincs fájl</div></div>';
    return;
  }
  for(const it of items){
    const row = document.createElement('div');
    row.className = 'item';
    row.innerHTML = `
      <div class="name">${it.path}</div>
      <div class="muted">${fmtSize(it.size)}</div>
      <div class="muted">${it.last_modified?new Date(it.last_modified).toLocaleString():'-'}</div>
      <div class="actions">
        <button class="btn" data-act="dl" data-path="${it.path}">Letöltés</button>
        <button class="btn dng" data-act="del" data-path="${it.path}">Törlés</button>
      </div>
    `;
    row.addEventListener('click', async (e)=>{
      const btn = e.target.closest('button'); if(!btn) return;
      const path = btn.dataset.path;
      if(btn.dataset.act==='dl'){
        const url = new URL('/download', api); url.searchParams.set('path', path);
        const r = await fetch(url);
        const blob = await r.blob();
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = path.split('/').pop();
        document.body.appendChild(a); a.click(); a.remove();
      } else if(btn.dataset.act==='del'){
        const url = new URL('/delete', api); url.searchParams.set('path', path);
        await fetch(url, { method: 'DELETE' }); refresh();
      }
    });
    listEl.appendChild(row);
  }
}

async function uploadFiles(files){
  const prefix = el('prefix').value || '';
  const base = prefix ? (prefix.endsWith('/')?prefix:prefix+'/') : '';
  let done = 0, total = Array.from(files).reduce((s,f)=>s+f.size,0);
  for(const f of files){
    const path = base + f.name;
    const fd = new FormData();
    fd.append('path', path);
    fd.append('file', f, f.name);
    const r = await fetch('/upload?'+new URLSearchParams({path}), {
      method: 'POST', body: fd
    });
    if(!r.ok){ console.error('Upload failed', await r.text()); continue; }
    done += f.size;
    bar.style.width = Math.min(100, (done/total)*100) + '%';
  }
  setTimeout(()=> bar.style.width='0%', 600);
  refresh();
}

const drop = el('drop');
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev, e=>{e.preventDefault(); drop.classList.add('drag');}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev, e=>{e.preventDefault(); drop.classList.remove('drag');}));
drop.addEventListener('drop', e=>{
  const files = e.dataTransfer.files;
  if(files && files.length) uploadFiles(files);
});

el('pick').addEventListener('click', ()=> el('file').click());
el('file').addEventListener('change', e=> uploadFiles(e.target.files));
el('refresh').addEventListener('click', refresh);
refresh();
</script>
</body>
</html>



 Telepítés és futtatás
 pip install "fastapi[standard]" uvicorn obstore [1]
 Opcionálisan objektumtár választás:
   memory: export STORE_URL=memory:// (alapértelmezett) [3]
   helyi könyvtár: export STORE_URL=file:///tmp/drive [1]
   S3: export STORE_URL=s3://mybucket (publikus vagy hitelesített) [3]
   GCS: export STORE_URL=gcs://mybucket [1]
 Indítás: uvicorn main:app reload [4]

 Miért gyors?
 Rustalapú, zerocopy, streaming, multipart feltöltések, async I/O, automatikus credential refresh; egy API minden backendhez[1][3].
 FastAPI UploadFile async kezelés nagy fájlokra optimalizálva[4][5].
 A range letöltés csökkenti a sávszélt nagy fájloknál[3].

Ha S3/GCSt használnál, állíts be megfelelő felhő hitelesítést; Obstore automatikusan kezeli és frissíti a credeket, vagy anonim módon eléri publikus bucketteket[3][1].
